// Generated by `just generate` from `src/plugins/claudetto-sessions/slices/usage/domain/text.ts`. Edit the source and run `just generate`.
// The text of the usage report: the lines that `claudetto-usage` prints for a report.

import {
  ADVISOR_CALLS,
  CACHE_HIT_RATE,
  CACHE_REWRITES,
  FIRST_WARM_CALL,
  MODEL_CALLS,
  OUTPUT_TOKENS,
  PERIOD_COST,
  TOOL_RESULTS_PER_SESSION,
  TURN_CAP_RUNS,
  UNKNOWN_MODELS,
  WAKE_TURNS,
} from "../prompts.ts";
import type { Report } from "./summary.ts";

const k = (n: number) => `${Math.round(n / 1000)}k`;
const n = (x: number) => x.toLocaleString("en-US");

/** The lines of the text report `r` for a period of `days` days. */
export const textOf = (
  r: Report,
  days: number,
  window: number | null,
): string[] => {
  const out = [PERIOD_COST({ days: String(days), total: String(r.total) })];
  for (const a of r.byAgent.slice(0, 10))
    out.push(
      `  ${a.type.padEnd(32)} $${a.cost.toFixed(2).padStart(9)}  ${a.share}%`,
    );
  out.push(
    `Calls with context past ${window ? k(window) : "the window of their model (200k, or 1M for a 1M model)"}: ${r.overWindowShare}% of cost`,
  );
  const o = r.output;
  out.push(
    OUTPUT_TOKENS({
      tokens: String(o.tokens),
      messages: String(o.messages),
      unfinished: String(o.unfinished),
    }),
  );
  const unknown = r.unknownModels;
  if (unknown.calls)
    out.push(
      UNKNOWN_MODELS({
        calls: String(unknown.calls),
        models: unknown.models.join(", "),
      }),
    );
  const e = r.expectedRewrites;
  out.push(
    CACHE_REWRITES({
      share: String(r.rewriteShare),
      expectedShare: String(r.expectedRewriteShare),
      first: String(e.first),
      compaction: String(e.compaction),
      model: String(e.model),
    }),
    WAKE_TURNS({
      wake: String(r.mainTurns.wake),
      all: String(r.mainTurns.wake + r.mainTurns.other),
      share: String(r.wakeShare),
    }),
    ADVISOR_CALLS({
      calls: String(r.advisor.calls),
      share: String(r.advisor.share),
    }),
    // The cost guide: below about 80%, something is breaking the cache.
    CACHE_HIT_RATE({
      all: String(r.cacheHitRate.all ?? "-"),
      main: String(r.cacheHitRate.main ?? "-"),
    }),
  );
  const f = r.firstCallAfterPrompt;
  out.push(
    FIRST_WARM_CALL({
      withShare: String(f.with.writeShare),
      withCalls: String(f.with.calls),
      withoutShare: String(f.without.writeShare),
      withoutCalls: String(f.without.calls),
    }),
  );
  // The largest count comes first, then the keys in order, so the line does not depend on the order of the files on disk.
  const list = (counts: Record<string, number>) =>
    Object.entries(counts)
      .sort(([a, m], [b, n]) => n - m || (a < b ? -1 : a > b ? 1 : 0))
      .map(([key, count]) => `${key} ${count}`)
      .join(", ") || "-";
  out.push(
    `Sessions by entrypoint: ${list(r.entrypoints)}`,
    `Wake turns by entrypoint: ${list(r.wakesByEntrypoint)}`,
    `Claude Code versions of the sessions: ${list(r.claudeCodeVersions)}`,
    ...(r.pluginVersions
      ? [`Plugin versions of the sessions: ${list(r.pluginVersions)}`]
      : []),
    `Usage-limit hits: ${r.limitHits}`,
    `Skill calls: ${r.skills.map((s) => `${s.skill} ${s.uses}`).join(", ") || "-"}`,
  );
  const c = r.calls;
  out.push(
    MODEL_CALLS({
      calls: n(c.calls),
      runs: String(c.runs),
      reread: n(c.reread),
    }),
    // biome-ignore lint/plugin: the header row is data, and the code aligns the columns under it
    `  run                          type                       calls  per call      largest         sum`,
  );
  for (const run of c.top)
    out.push(
      `  ${run.id.slice(0, 28).padEnd(28)} ${run.type.slice(0, 24).padEnd(24)} ${String(run.calls).padStart(7)} ${n(run.rereadPerCall).padStart(9)} ${n(run.rereadMax).padStart(12)} ${n(run.reread).padStart(11)}`,
    );
  const u = r.unusedSkills;
  out.push(
    `Skills that the period did not use: ${u.unused.length} of ${u.available} available. Source: ${u.source}`,
  );
  for (const s of u.unused)
    out.push(
      `  ${s.skill}${s.chars ? ` (${s.chars} chars in the listing)` : ""}`,
    );
  const d = r.delegation;
  out.push(
    `Delegation: ${d.runs} subagent runs in ${d.mainCalls} main calls, ${d.runsPer100Calls ?? "-"} per 100 calls (${d.runsByType.map((t) => `${t.type} ${t.runs}`).join(", ") || "-"})`,
    TOOL_RESULTS_PER_SESSION({
      median: String(d.resultTokensPerSession.median),
      p90: String(d.resultTokensPerSession.p90),
      sessions: String(d.resultTokensPerSession.sessions),
    }),
    `Latest ${d.latestRuns.length} subagent runs:`,
  );
  for (const run of d.latestRuns)
    out.push(
      `  ${run.id.slice(0, 8).padEnd(8)} ${run.type.slice(0, 24).padEnd(24)} $${run.cost.toFixed(2).padStart(6)}  ${run.description.slice(0, 40)} | ${run.handback}`,
    );
  if (r.turnCap.runs) {
    const other = new Map(r.turnCap.other.map((x) => [x.type, x] as const));
    out.push(
      TURN_CAP_RUNS({
        capped: String(r.turnCap.capped.reduce((m, x) => m + x.runs, 0)),
        runs: String(r.turnCap.runs),
      }),
    );
    for (const x of r.turnCap.capped) {
      const y = other.get(x.type) ?? { runs: 0, files: 0, items: 0 };
      out.push(
        `  ${x.type.padEnd(32)} ${x.runs} of ${x.runs + y.runs}  files ${x.files} vs ${y.files}  items ${x.items} vs ${y.items}`,
      );
    }
  }
  return out;
};
